      const parents=el('div','nc-parent-actions');for(const [key,label] of [['fixed',w.parentFixed],['weighted',w.parentWeighted]]){const button=el('button','',label),parent=s[key].parent[i];button.type='button';button.disabled=!(parent>=0);button.addEventListener('click',()=>this.inspect(source,parent,true));parents.append(button);}
